entries[29713] = { ["name"] = "Muster: Trommeln der Panik", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (370)\nBenötigt Hüter der Zeit\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung von Trommeln der Panik.\nVerkaufspreis:\nTrommeln der Panik\nBenötigt Lederverarbeitung (350)\nBenutzen: Unheimliche Klänge lassen 5 Gegner innerhalb von 5 Metern 2 Sek. lang voller Schrecken flüchten. (2 Min Abklingzeit)\n50 Aufladungen\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Teufelsbalg (4)" }
entries[29714] = { ["name"] = "Muster: Trommeln der Wiederherstellung", ["text"] = "Benötigt Lederverarbeitung (350)\nBenutzen: Lehrt Euch die Herstellung von Trommeln der Wiederherstellung.\nVerkaufspreis:\nTrommeln der Wiederherstellung\nBenötigt Lederverarbeitung (350)\nBenutzen: Stellt 15 Sek. lang insgesamt 600 Gesundheit und Mana bei allen in der Nähe befindlichen Gruppenmitgliedern wieder her. Unwirksam bei Zielen auf Stufe 80 oder höher. (2 Min Abklingzeit)\n50 Aufladungen\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Netherdrachenschuppe (4)" }
entries[29717] = { ["name"] = "Muster: Trommeln der Schlacht", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (365)\nBenötigt Die Sha'tar\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung von Trommeln der Schlacht.\nVerkaufspreis:\nTrommeln der Schlacht\nBenötigt Lederverarbeitung (350)\nBenutzen: Erhöht die Tempowertung aller in der Nähe befindlichen Gruppenmitglieder um bis zu 80. Hält 30 Sek. lang an. Unwirksam bei Zielen auf Stufe 80 oder höher. (2 Min Abklingzeit)\n50 Aufladungen\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Dickes Grollhufleder (4)" }
entries[29718] = { ["name"] = "Muster: Trommeln des Tempos", ["text"] = "Benötigt Lederverarbeitung (345)\nBenutzen: Lehrt Euch die Herstellung von Trommeln des Tempos.\nVerkaufspreis:\nTrommeln des Tempos\nBenötigt Lederverarbeitung (340)\nBenutzen: Erhöht das Bewegungstempo aller in der Nähe befindlichen Gruppenmitglieder um 15%. Hält 30 Sek. lang an. (2 Min Abklingzeit)\n50 Aufladungen\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Windschuppen (4)" }
