entries[30316] = { ["name"] = "Macht der Verwüstung", ["text"] = "Festung der Stürme\nEinzigartig\nDauer: 15 min (Realzeit)Zweihändig Axt\n496 - 744 Schaden Tempo 3.90\n(158.97 Schaden pro Sekunde)\n+75 Ausdauer\nHaltbarkeit 145 / 145\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Trefferwertung um 50.\nAnlegen: Erhöht die Angriffskraft um 150.\nTrefferchance: Erhöht 30 Sek. lang das Bewegungstempo um 50% und das Nahkampfangriffstempo um 20%." }
entries[30317] = { ["name"] = "Kosmische Macht", ["text"] = "Festung der Stürme\nEinzigartig\nDauer: 15 min (Realzeit)Waffenhand Streitkolben\n239 - 445 Schaden Tempo 2.80\n(122.14 Schaden pro Sekunde)\n+75 Ausdauer\n+87 Willenskraft\nHaltbarkeit 130 / 130\nBenötigt Stufe 70\nAnlegen: Erhöht die Zaubermacht um 398.\nAnlegen: Befreundete Ziele der Heilung des Zaubernden erhalten einen Effekt, der 30 Sek. lang erlittenen Feuer- und Schattenschaden um 50% verringert." }
entries[30318] = { ["name"] = "Netherbespannter Langbogen", ["text"] = "Festung der Stürme\nEinzigartig\nDauer: 15 min (Realzeit)Distanz Bogen\n368 - 553 Schaden Tempo 2.90\n(158.79 Schaden pro Sekunde)\n+20 Ausdauer\nHaltbarkeit 110 / 110\nKlassen: Jäger , Todesritter\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Distanztrefferwertung um 50.\nAnlegen: Erhöht die Distanzangriffskraft um 70.\nAnlegen: Erhöht Euren Schadensbonus für kritische Treffer durch Distanzwaffen um 50%.\nTrefferchance: Erhöht den zugefügten körperlichen Schaden um 5%. Kann bis zu 5-mal angewendet werden. Hält 30 Sek. lang an." }
